&#34;&gt;.&lt;/span&gt;systemUiVisibility&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;v &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; v &lt;span class=&#34;token operator&#34;&gt;or&lt;/span&gt;  View&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;SYSTEM_UI_FLAG_FULLSCREEN &lt;span class=&#34;token operator&#34;&gt;or&lt;/span&gt; View&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;window&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;decorView&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;systemUiVisibility &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; v&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// 知道了，知道了，是因为 ** 异形屏 ** 导致的，需要配置 layoutInDisplayCutoutMode 参数&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token comment&#34;&gt;// 完整正常 扩展到状态栏，且隐藏状态栏代码&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;span class=&#34;token keyword&#34;&gt;val&lt;/span&gt; lp &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt; window&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;attributes&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;14&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;lp&lt;span class=&#34;token punctuation&#34;&gt;.&lt;/span&gt;layoutInDisplayCutoutMode &lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;15&#34;&gt;&lt;/td&gt;&l